: "比例关系搞混"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忽略某个量是固定的条件"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "比例行程的核心是\"固定一个量看另外两个的关系\"。建议先判断正反比再用份数法。"}]}]}]}$$ AS jsonb), NULL, '数量关系-行程问题-比例行程的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "行程问题", "比例行程"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_travel_ratio", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
